/** One destination of the bottom navigation: the word, its outline icon and the filled icon for the current item. */
@Immutable
data class SbNavItem(val label: String, val icon: ImageVector, val selectedIcon: ImageVector = icon)

/** Bottom navigation with icon AND word for every destination (D36); the current item carries the 3 dp accent edge. */
@Composable
fun SbNavigationBar(
    items: List<SbNavItem>,
    selectedIndex: Int,
    onSelect: (Int) -> Unit,
    modifier: Modifier = Modifier,
) {
    require(items.size in 3..5) { "SbNavigationBar: 3 to 5 destinations, got ${items.size}" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    Row(modifier.fillMaxWidth().selectableGroup()) {
        items.forEachIndexed { index, item ->
            val selected = index == selectedIndex
            val interaction = remember { MutableInteractionSource() }
            val tint = if (selected) c.link else c.textMuted
            val edge = t.borderWidth.strong
            Column(
                Modifier
                    .weight(1f)
                    .sbFocusRing(interaction, t.radius.control)
                    .heightIn(min = t.space.s16)
                    .selectable(
                        selected = selected,
                        interactionSource = interaction,
                        indication = null,
                        role = Role.Tab,
                        onClick = { onSelect(index) },
                    )
                    .drawBehind { if (selected) drawRect(c.accent, size = Size(size.width, edge.toPx())) }
                    .padding(vertical = t.space.s2),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(t.space.s0_5, Alignment.CenterVertically),
            ) {
                Icon(
                    if (selected) item.selectedIcon else item.icon,
                    contentDescription = null,
                    tint = tint,
                    modifier = Modifier.size(t.size.iconLg),
                )
                // D99 (1): at a large font scale the word wraps (a word wider than the item is hyphenated) and the bar
                // grows; never cut
                val word = if (selected) ty.labelSmall.copy(fontWeight = ty.title.fontWeight) else ty.labelSmall
                SbWrapText(item.label, word, tint, center = true)
            }
        }
    }
}
